function setExportMenuOpen(open){$('#exportScreenMenu').hidden=!open;$('#exportScreenButton').setAttribute('aria-expanded',String(open))}function exportScreen(){const miniApps={};miniAppRegistry.forEach((miniApp,id)=>{miniApps[id]=miniApp.exportState?.()??{}});const state={format:'schola-classroom-screen',version:1,app:'Classroom Screen',exportedAt:new Date().toISOString(),miniApps};const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='classroom-screen.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0)}
