scheduleWidget.querySelector('.classroom-schedule-close').onclick=()=>{scheduleState.visible=false;saveScheduleState();renderScheduleWidget()};let scheduleDrag=null;scheduleWidget.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;event.preventDefault();const stage=$('.screen-stage'),stageRect=stage.getBoundingClientRect(),rect=scheduleWidget.getBoundingClientRect();if(!Number.isFinite(scheduleState?.layout?.x)||!Number.isFinite(scheduleState?.layout?.y)){scheduleState.layout={x:rect.left-stageRect.left+stage.scrollLeft,y:rect.top-stageRect.top+stage.scrollTop};applyScheduleWidgetLayout()}scheduleDrag={startX:event.clientX,startY:event.clientY,x:scheduleState.layout.x,y:scheduleState.layout.y};scheduleWidget.setPointerCapture?.(event.pointerId)});scheduleWidget.addEventListener('pointermove',event=>{if(!scheduleDrag)return;scheduleState.layout.x=scheduleDrag.x+event.clientX-scheduleDrag.startX;scheduleState.layout.y=scheduleDrag.y+event.clientY-scheduleDrag.startY;applyScheduleWidgetLayout()});scheduleWidget.addEventListener('pointerup',()=>{if(scheduleDrag)saveScheduleState();scheduleDrag=null});applyScheduleWidgetLayout();renderScheduleWidget();setInterval(()=>renderScheduleWidget(),1000);
const menu=$('#sideMenu'),overlay=$('#menuOverlay'),menuButton=$('#menuButton');const drawer=o=>{menu.classList.toggle('open',o);menu.inert=!o;overlay.hidden=!o;menuButton.setAttribute('aria-expanded',String(o))};menuButton.onclick=()=>drawer(true);$('#menuCloseButton').onclick=overlay.onclick=()=>drawer(false);$('#openWorkspaceButton').onclick=()=>app.classList.add('workspace-open');$('#returnScreenButton').onclick=()=>app.classList.remove('workspace-open');$('#timerToolButton').onclick=()=>setWidgetVisible(widget.hidden);$('#closeTimerButton').onclick=()=>setWidgetVisible(false);textToolButton.onclick=()=>{$('#typeMapIdInput').value=typeMapTextState?.sourceId?`TM1:${typeMapTextState.sourceId}`:'';$('#typeMapIdStatus').textContent='';textDialog.showModal()};$('#closeTextDialogButton').onclick=$('#cancelTextDialogButton').onclick=()=>textDialog.close();$('#insertTypeMapButton').onclick=insertTypeMapText;$('#refreshTypeMapTextButton').onclick=refreshTypeMapText;const addTimer=$('[data-add-tool="timer"]');if(addTimer)addTimer.onclick=()=>{setWidgetVisible(true);$('#moreMenu').hidden=true};$('#clearScreenButton').onclick=clearScreen;$('#exportScreenButton').onclick=e=>{e.stopPropagation();setExportMenuOpen($('#exportScreenButton').getAttribute('aria-expanded')!=='true')};$('#exportScreenMenu').onclick=e=>{const option=e.target.closest('[data-export-format]');if(!option)return;e.stopPropagation();setExportMenuOpen(false);if(option.dataset.exportFormat==='json')exportScreen()};document.addEventListener('click',e=>{if(!e.target.closest('.schola-export-control'))setExportMenuOpen(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')setExportMenuOpen(false)});$('#moreToolButton').onclick=()=>{$('#moreMenu').hidden=!$('#moreMenu').hidden};$('#closeMoreButton').onclick=()=>$('#moreMenu').hidden=true;dial.tabIndex=0;dial.onclick=()=>{if(timerMoved){timerMoved=false;return}if(running)toggle();else if(!remaining)stop()};ticks();selectTab(0);rebuild();renderPhaseN